/**
 * Trusted workspace instructions: one named file the project's owner explicitly vouches for.
 *
 * There are three trust levels in a run's context. The application's own text is generated by code
 * (src/harness.ts). A project's `instructions` field and, here, ONE workspace file are written by
 * the owner and join the trusted system context. Everything else that is read (indexed documents,
 * PDFs, chats, transcripts, web pages) is untrusted evidence and never reaches the system context,
 * however it is named: a file called AGENTSPINE.md inside an indexed folder is only a chunk of
 * knowledge, tagged UNTRUSTED, unless the owner has pointed the project at it.
 *
 * Pointing a project at a file is therefore a privilege, and it is guarded three ways. The file must
 * be named exactly AGENTSPINE.md, must sit inside one of the project's own path sources, and must NOT
 * sit inside any folder the agent can write to (`policy.fs.writableDirs`): otherwise a run that read
 * a hostile page could rewrite the rules that every later run in the project follows. All three are
 * checked again every time the file is read, because a symlink or a policy can change.
 */
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import * as projects from "./store.ts";
import type { Policy } from "../types.ts";

export const WORKSPACE_FILE = "AGENTSPINE.md";
const MAX_CHARS = 8000;

const expand = (p: string): string => (p === "~" || p.startsWith("~/") ? path.join(os.homedir(), p.slice(1)) : p);

const real = (p: string): null | string => {
  try {
    return fs.realpathSync(expand(p));
  } catch {
    return null;
  }
};

const inside = (child: string, parent: string): boolean => child === parent || child.startsWith(parent.endsWith(path.sep) ? parent : parent + path.sep);

export type WorkspaceCheck = { ok: false; reason: string } | { ok: true; real: string };

/** Whether `filePath` may be trusted as this project's workspace instructions. */
export const checkWorkspaceFile = (projectId: number, filePath: string, policy: Policy): WorkspaceCheck => {
  const resolved = real(filePath);
  if (!resolved) return { ok: false, reason: "that file does not exist" };
  if (path.basename(resolved) !== WORKSPACE_FILE) return { ok: false, reason: `only a file named ${WORKSPACE_FILE} can be trusted` };
  try {
    if (!fs.statSync(resolved).isFile()) return { ok: false, reason: "that is not a regular file" };
  } catch {
    return { ok: false, reason: "that file cannot be read" };
  }
  const roots = projects
    .listSources(projectId)
    .filter((s) => s.kind === "path")
    .map((s) => real(s.ref))
    .filter((r): r is string => r !== null);
  if (!roots.some((r) => inside(resolved, r))) return { ok: false, reason: "it must sit inside one of this project's own folders" };
  const writable = (policy.fs?.writableDirs ?? []).map(real).filter((r): r is string => r !== null);
  if (writable.some((w) => inside(resolved, w))) {
    return { ok: false, reason: "it sits in a folder the assistant can write to, so a run could rewrite its own rules; move it out of writableDirs" };
  }
  return { ok: true, real: resolved };
};

/** The trusted text and where it came from, or null when there is none or it no longer qualifies. */
export const workspaceInstructions = (projectId: number, policy: Policy): null | { source: string; text: string } => {
  const project = projects.getProject(projectId);
  if (!project?.instructions_file) return null;
  const check = checkWorkspaceFile(projectId, project.instructions_file, policy);
  if (!check.ok) return null;
  try {
    const text = fs.readFileSync(check.real, "utf8").trim().slice(0, MAX_CHARS);
    return text ? { source: `workspace file ${WORKSPACE_FILE}`, text } : null;
  } catch {
    return null;
  }
};
